pub fn loop_edge_contributes_to_iteration_fold(parent: Rc<Node>, e: Rc<Edge>) -> bool {
    match (*parent.kind.clone()).clone() {
        NodeKind::ComputationNode {
            behavior: Behavior::Loop,
            ..
        } => match (*e.label.clone()).clone() {
            EdgeLabel::Positional => true,
            EdgeLabel::Named { name: sym, .. } => {
                ((sym.clone() != "loop_bound_edge".to_string())
                    && (sym.clone() != "loop_carrier_edge".to_string()))
            }
        },
        _ => match (*e.label.clone()).clone() {
            EdgeLabel::Positional => true,
            EdgeLabel::Named { name: _, .. } => true,
        },
    }
}

