pub fn edge_contributes_to_cost_fold(parent: Rc<Node>, e: Rc<Edge>) -> bool {
    match (*parent.kind.clone()).clone() {
        NodeKind::ComputationNode {
            behavior: Behavior::Loop,
            ..
        } => match (*e.label.clone()).clone() {
            EdgeLabel::Positional => true,
            EdgeLabel::Named { name: sym, .. } => {
                ((sym.clone() != "loop_bound_edge".to_string())
                    && (sym.clone() != "loop_carrier_edge".to_string()))
            }
        },
        NodeKind::TypeNode { ref connective, .. }
            if matches!(connective.as_ref(), Connective::Arrow) =>
        {
            let Connective::Arrow = connective.as_ref() else {
                unreachable!()
            };
            match (*e.label.clone()).clone() {
                EdgeLabel::Positional => false,
                EdgeLabel::Named { name: sym, .. } => {
                    (sym.clone() == "arrow_body_edge".to_string())
                }
            }
        }
        _ => match (*e.label.clone()).clone() {
            EdgeLabel::Positional => true,
            EdgeLabel::Named { name: _, .. } => true,
        },
    }
}

pub fn all_names_distinct(children: Rc<Vec<Rc<Edge>>>) -> bool {
    children
        .clone()
        .iter()
        .cloned()
        .fold(true, |acc: bool, e: Rc<Edge>| {
            match (*e.label.clone()).clone() {
                EdgeLabel::Named { name: n, .. } => {
                    (acc.clone() && (name_occurrences(n.clone(), children.clone()) == 1))
                }
                EdgeLabel::Positional => acc.clone(),
            }
        })
}

pub fn edges_conform(children: Rc<Vec<Rc<Edge>>>, d: EdgeDiscipline) -> bool {
    match d.clone() {
        EdgeDiscipline::NoEdges => ((children.clone().len() as i64) == 0),
        EdgeDiscipline::LabeledEdges => {
            (all_edges_named(children.clone()) && all_names_distinct(children.clone()))
        }
        EdgeDiscipline::PositionalEdges => all_edges_positional(children.clone()),
        EdgeDiscipline::LoopBoundEdges => loop_behavior_edges_conform(children.clone()),
        EdgeDiscipline::ArrowBodyEdges => arrow_body_edges_conform(children.clone()),
    }
}

pub fn connective_edges_conform(children: Rc<Vec<Rc<Edge>>>, c: Rc<Connective>) -> bool {
    match (*c.clone()).clone() {
        Connective::Atom { identity: _, .. } => edges_conform(
            children.clone(),
            connective_edge_discipline_for_children(c.clone(), children.clone()),
        ),
        Connective::Conj => edges_conform(children.clone(), EdgeDiscipline::LabeledEdges),
        Connective::Disj => edges_conform(children.clone(), EdgeDiscipline::LabeledEdges),
        Connective::Arrow => arrow_body_edges_conform(children.clone()),
        Connective::Cardinality => {
            (edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && ((children.clone().len() as i64) >= 1))
        }
        Connective::Instantiation => {
            (edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && ((children.clone().len() as i64) >= 1))
        }
    }
}

pub fn match_arm_node_conforms(arm: Rc<Node>) -> bool {
    match (*arm.kind.clone()).clone() {
        NodeKind::TypeNode { ref connective, .. }
            if matches!(connective.as_ref(), Connective::Conj) =>
        {
            let Connective::Conj = connective.as_ref() else {
                unreachable!()
            };
            ((name_occurrences(match_arm_pattern(), arm.children.clone()) == 1)
                && (name_occurrences(match_arm_body(), arm.children.clone()) == 1))
        }
        _ => false,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct MatchArmChildrenConformFold {
    pub ok: bool,
    pub skipped_scrutinee: bool,
}

pub fn match_arm_children_conform_skip_first(
    children: Rc<Vec<Rc<Edge>>>,
    skipped_scrutinee: bool,
) -> bool {
    {
        let folded = children.clone().iter().cloned().fold(
            MatchArmChildrenConformFold {
                ok: true,
                skipped_scrutinee: skipped_scrutinee.clone(),
            },
            |acc: MatchArmChildrenConformFold, edge: Rc<Edge>| {
                if !acc.ok.clone() {
                    acc.clone()
                } else {
                    match (*edge.label.clone()).clone() {
                        EdgeLabel::Positional => {
                            if !acc.skipped_scrutinee.clone() {
                                MatchArmChildrenConformFold {
                                    ok: true,
                                    skipped_scrutinee: true,
                                }
                            } else {
                                if !match_arm_node_conforms(edge.target.clone()) {
                                    MatchArmChildrenConformFold {
                                        ok: false,
                                        skipped_scrutinee: true,
                                    }
                                } else {
                                    MatchArmChildrenConformFold {
                                        ok: true,
                                        skipped_scrutinee: true,
                                    }
                                }
                            }
                        }
                        EdgeLabel::Named { name: _, .. } => acc.clone(),
                    }
                }
            },
        );
        (folded.ok.clone() && folded.skipped_scrutinee.clone())
    }
}

pub fn behavior_edges_conform(children: Rc<Vec<Rc<Edge>>>, b: Behavior) -> bool {
    match b.clone() {
        Behavior::Value => ((children.clone().len() as i64) == 0),
        Behavior::Transform => {
            (edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && ((children.clone().len() as i64) >= 1))
        }
        Behavior::Branch => {
            (edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && ((children.clone().len() as i64) >= 1))
        }
        Behavior::Loop => edges_conform(children.clone(), EdgeDiscipline::LoopBoundEdges),
        Behavior::Bind => {
            (edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && ((children.clone().len() as i64) == 3))
        }
        Behavior::Match => {
            ((edges_conform(children.clone(), EdgeDiscipline::PositionalEdges)
                && (positional_child_count(children.clone()) >= 2))
                && match_arm_children_conform_skip_first(children.clone(), false))
        }
    }
}

pub fn locally_well_formed(n: Rc<Node>) -> bool {
    match (*n.kind.clone()).clone() {
        NodeKind::TypeNode { connective: c, .. } => {
            connective_edges_conform(n.children.clone(), c.clone())
        }
        NodeKind::ComputationNode { behavior: b, .. } => {
            behavior_edges_conform(n.children.clone(), b.clone())
        }
    }
}

pub fn well_formed(n: Rc<Node>) -> bool {
    fold_node(
        n.clone(),
        Rc::new(NodeFold {
            init: Rc::new(|n0| locally_well_formed(n0.clone())),
            step: Rc::new(|acc, _, child_ok| (acc.clone() && child_ok.clone())),
            _phantom: std::marker::PhantomData,
        }),
    )
}

pub fn is_empty_conj_root(n: Rc<Node>) -> bool {
    match (*n.kind.clone()).clone() {
        NodeKind::TypeNode { ref connective, .. }
            if matches!(connective.as_ref(), Connective::Conj) =>
        {
            let Connective::Conj = connective.as_ref() else {
                unreachable!()
            };
            ((n.children.clone().len() as i64) == 0)
        }
        _ => false,
    }
}

pub fn behavior_edge_discipline(b: Behavior) -> EdgeDiscipline {
    match b.clone() {
        Behavior::Value => EdgeDiscipline::NoEdges,
        Behavior::Transform => EdgeDiscipline::PositionalEdges,
        Behavior::Branch => EdgeDiscipline::PositionalEdges,
        Behavior::Loop => EdgeDiscipline::LoopBoundEdges,
        Behavior::Bind => EdgeDiscipline::PositionalEdges,
        Behavior::Match => EdgeDiscipline::PositionalEdges,
    }
}

pub fn node_edge_discipline(n: Rc<Node>) -> EdgeDiscipline {
    match (*n.kind.clone()).clone() {
        NodeKind::TypeNode { connective: c, .. } => {
            connective_edge_discipline_for_children(c.clone(), n.children.clone())
        }
        NodeKind::ComputationNode { behavior: b, .. } => behavior_edge_discipline(b.clone()),
    }
}

