pub fn canonicalize_node_for_content_hash(n: Rc<Node>) -> Rc<Node> {
    {
        let base = node_for_structural_equality(n.clone());
        match node_edge_discipline(n.clone()) {
            EdgeDiscipline::LabeledEdges => Rc::new(Node {
                kind: base.kind.clone(),
                children: Rc::new({
                    let mut __sorted: Vec<_> = base.children.clone().iter().cloned().collect();
                    __sorted.sort_by(|a: &Rc<Edge>, b: &Rc<Edge>| {
                        let __ka = (|e: Rc<Edge>| named_edge_sort_key(e.clone()))(a.clone());
                        let __kb = (|e: Rc<Edge>| named_edge_sort_key(e.clone()))(b.clone());
                        __ka.partial_cmp(&__kb).unwrap_or(std::cmp::Ordering::Equal)
                    });
                    __sorted
                }),
                occurrence_id: Rc::new(NodeOccurrenceId::SyntheticOccurrence),
            }),
            EdgeDiscipline::NoEdges => Rc::new(Node {
                kind: base.kind.clone(),
                children: base.children.clone(),
                occurrence_id: Rc::new(NodeOccurrenceId::SyntheticOccurrence),
            }),
            EdgeDiscipline::PositionalEdges => Rc::new(Node {
                kind: base.kind.clone(),
                children: base.children.clone(),
                occurrence_id: Rc::new(NodeOccurrenceId::SyntheticOccurrence),
            }),
            EdgeDiscipline::ArrowBodyEdges => Rc::new(Node {
                kind: base.kind.clone(),
                children: canonicalize_arrow_children_for_content_hash(base.children.clone()),
                occurrence_id: Rc::new(NodeOccurrenceId::SyntheticOccurrence),
            }),
            EdgeDiscipline::LoopBoundEdges => Rc::new(Node {
                kind: base.kind.clone(),
                children: canonicalize_loop_children_for_content_hash(base.children.clone()),
                occurrence_id: Rc::new(NodeOccurrenceId::SyntheticOccurrence),
            }),
        }
    }
}

pub fn fold_node_content_hash<R: Clone>(n: Rc<Node>, algebra: Rc<NodeFold<R>>) -> R {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let n = canonicalize_node_for_content_hash(n.clone());
        n.children
            .clone()
            .iter()
            .cloned()
            .fold((algebra.init)(n.clone()), |acc: _, e: Rc<Edge>| {
                (algebra.step)(
                    acc,
                    e.clone(),
                    fold_node_content_hash(e.target.clone(), algebra.clone()),
                )
            })
    })
}

