pub fn byte_limb_hash_peano_digest(limb: i64) -> Rc<Fnv1a64Structural> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if ((limb.clone() < 0) || (limb.clone() > 255)) {
            crate::std_content_hash::content_hash_atom(
                "canonical_tag_byte_limb_out_of_range".to_string(),
            )
        } else {
            if (limb.clone() == 0) {
                crate::std_content_hash::content_hash_atom(
                    "canonical_tag_scalar_int_zero".to_string(),
                )
            } else {
                if (limb.clone() == 1) {
                    crate::std_content_hash::content_hash_atom(
                        "canonical_tag_scalar_int_one".to_string(),
                    )
                } else {
                    combine_hash(
                        crate::std_content_hash::content_hash_atom(
                            "canonical_tag_scalar_int_succ".to_string(),
                        ),
                        byte_limb_hash_peano_digest((limb.clone() - 1)),
                    )
                }
            }
        }
    })
}

pub fn byte_offset_byte_digest(b: i64) -> Rc<Fnv1a64Structural> {
    combine_hash(
        crate::std_content_hash::content_hash_atom("canonical_tag_byte_offset_byte".to_string()),
        byte_limb_hash_peano_digest(b.clone()),
    )
}

pub fn byte_offset_quotient_divide_by_256_steps(mut quotient: i64, mut steps: i64) -> i64 {
    loop {
        if (steps.clone() <= 0) {
            break quotient;
        } else {
            {
                let __tco_0 = (quotient / 256);
                let __tco_1 = (steps - 1);
                quotient = __tco_0;
                steps = __tco_1;
                continue;
            }
        }
    }
}

pub fn byte_offset_residual_quotient_magnitude_window_digest(
    quotient: i64,
    shift_steps: i64,
) -> Rc<Fnv1a64Structural> {
    {
        let shifted =
            byte_offset_quotient_divide_by_256_steps(quotient.clone(), shift_steps.clone());
        if ((shift_steps.clone() == byte_offset_residual_quotient_magnitude_max_shift())
            && (shifted.clone() >= (256 * 256)))
        {
            combine_hash(
                byte_offset_residual_quotient_limb_pair_digest(shifted.clone()),
                byte_offset_overflow_quotient_high_band_terminal_digest(
                    (shifted.clone() / 65536),
                    byte_offset_cache_digest_overflow_limbs(),
                ),
            )
        } else {
            byte_offset_residual_quotient_limb_pair_digest(shifted.clone())
        }
    }
}

pub fn byte_offset_residual_quotient_limb_pair_digest(quotient: i64) -> Rc<Fnv1a64Structural> {
    if (quotient.clone() < (256 * 256)) {
        combine_hash(
            crate::std_content_hash::content_hash_atom(
                "canonical_tag_byte_offset_residual_quotient_limb_pair".to_string(),
            ),
            combine_hash(
                byte_offset_byte_digest((quotient.clone() - ((quotient.clone() / 256) * 256))),
                byte_offset_byte_digest((quotient.clone() / 256)),
            ),
        )
    } else {
        combine_hash(
            crate::std_content_hash::content_hash_atom(
                "canonical_tag_byte_offset_overflow_residual_discarded_high_truncated".to_string(),
            ),
            combine_hash(
                byte_offset_byte_digest((quotient.clone() - ((quotient.clone() / 256) * 256))),
                byte_offset_byte_digest(
                    ((quotient.clone() / 256) - ((quotient.clone() / 65536) * 256)),
                ),
            ),
        )
    }
}

pub fn byte_offset_residual_quotient_magnitude_digest(quotient: i64) -> Rc<Fnv1a64Structural> {
    combine_hash(
        crate::std_content_hash::content_hash_atom(
            "canonical_tag_byte_offset_residual_quotient_magnitude".to_string(),
        ),
        combine_hash(
            byte_offset_residual_quotient_magnitude_window_digest(quotient.clone(), 0),
            combine_hash(
                byte_offset_residual_quotient_magnitude_window_digest(
                    quotient.clone(),
                    byte_offset_residual_quotient_magnitude_shift_limbs(),
                ),
                combine_hash(
                    byte_offset_residual_quotient_magnitude_window_digest(quotient.clone(), 8),
                    combine_hash(
                        byte_offset_residual_quotient_magnitude_window_digest(quotient.clone(), 12),
                        combine_hash(
                            byte_offset_residual_quotient_magnitude_window_digest(
                                quotient.clone(),
                                16,
                            ),
                            combine_hash(
                                byte_offset_residual_quotient_magnitude_window_digest(
                                    quotient.clone(),
                                    20,
                                ),
                                combine_hash(
                                    byte_offset_residual_quotient_magnitude_window_digest(
                                        quotient.clone(),
                                        24,
                                    ),
                                    byte_offset_residual_quotient_magnitude_window_digest(
                                        quotient.clone(),
                                        byte_offset_residual_quotient_magnitude_max_shift(),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
    )
}

pub fn byte_offset_overflow_quotient_high_band_terminal_digest(
    quotient: i64,
    limbs_remaining: i64,
) -> Rc<Fnv1a64Structural> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (limbs_remaining.clone() == 0) {
            if (quotient.clone() == 0) {
                crate::std_content_hash::content_hash_atom(
                    "canonical_tag_byte_offset_zero".to_string(),
                )
            } else {
                if (quotient.clone() < (256 * 256)) {
                    combine_hash(
                        crate::std_content_hash::content_hash_atom(
                            "canonical_tag_byte_offset_overflow_peel_exhausted".to_string(),
                        ),
                        combine_hash(
                            byte_offset_byte_digest(
                                (quotient.clone() - ((quotient.clone() / 256) * 256)),
                            ),
                            byte_offset_byte_digest((quotient.clone() / 256)),
                        ),
                    )
                } else {
                    byte_offset_residual_quotient_limb_pair_digest(quotient.clone())
                }
            }
        } else {
            if (quotient.clone() == 0) {
                crate::std_content_hash::content_hash_atom(
                    "canonical_tag_byte_offset_zero".to_string(),
                )
            } else {
                combine_hash(
                    byte_offset_byte_digest((quotient.clone() - ((quotient.clone() / 256) * 256))),
                    byte_offset_overflow_quotient_high_band_terminal_digest(
                        (quotient.clone() / 256),
                        (limbs_remaining.clone() - 1),
                    ),
                )
            }
        }
    })
}

